#!/usr/bin/env bash
# Build a native `psc` bootstrap from the checked-in stage0 C bundle.
#
# The published releases used to ship a legacy `pengu` CLI, which is far too
# slow to compile this tree. `bootstrap/psc_stage0.c` is generated by a native
# `psc` (see tools/gen_stage0.sh) and only needs a C compiler + ar, so CI can
# bootstrap deterministically on Linux, macOS and Windows/MSYS2.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
STAGE0="$ROOT/bootstrap/psc_stage0.c"
OUT="$ROOT/build/psc-stage0"

if [ -z "${CC:-}" ]; then
  if command -v cc >/dev/null 2>&1; then
    CC=cc
  elif command -v gcc >/dev/null 2>&1; then
    CC=gcc
  elif command -v clang >/dev/null 2>&1; then
    CC=clang
  else
    echo "build_bootstrap: no C compiler found (set CC)" >&2
    exit 1
  fi
fi
export CC
export AR="${AR:-ar}"

[ -f "$STAGE0" ] || { echo "build_bootstrap: missing $STAGE0" >&2; exit 1; }

"$ROOT/tools/build_runtime.sh"

os="$(uname -s | tr '[:upper:]' '[:lower:]')"
case "$os" in
  linux*) libs=(-lm -pthread -ldl) ;;
  mingw*|msys*|cygwin*)
    # MinGW/SDS emit a few harmless warnings while building stage0.
    export PENGU_NO_WERROR=1
    libs=(-lm -pthread -lws2_32)
    ;;
  *) libs=(-lm -pthread) ;;
esac

"$CC" -std=c11 -O2 \
  -I"$ROOT" -I"$ROOT/build/include" -I"$ROOT/std_c" -I"$ROOT/std_c/sds" \
  "$STAGE0" \
  "$ROOT/build/lib/libpengu_runtime.a" \
  "$ROOT/build/lib/libminiz.a" \
  "$ROOT/build/lib/libre.a" \
  "${libs[@]}" \
  -o "$OUT"

"$OUT" version
